            if common:
                bg = max(common, key=lambda v: sum(x == v for rows in (top, bottom) for row in rows for x in row))
            else:
                bg = grid[r][0]
            return [[3 if top[i][j] == bottom[i][j] else bg
                     for j in range(w)] for i in range(n)]

    for c in range(w):
        if len({grid[r][c] for r in range(h)}) == 1:
            left = [row[:c] for row in grid]
            right = [row[c + 1:] for row in grid]
            width = min(len(left[0]), len(right[0]))
            common = set(v for row in left for v in row) & set(v for row in right for v in row)
            bg = max(common, key=lambda v: sum(x == v for rows in (left, right) for row in rows for x in row)) if common else grid[0][c]
            return [[3 if left[i][j] == right[i][j] else bg
                     for j in range(width)] for i in range(h)]

    return grid
